function validate(input) {
  const [{ Purchases = [] }] = input;
  const ids = new Set();
  for (const [id, user, date] of Purchases) {
    if (id === null || user === null || date === null) return 'Purchases rows may not contain null.';
    if (ids.has(id)) return `purchase_id ${id} appears twice in Purchases.`;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return `purchase_date ${date} is not a date.`;
    ids.add(id);
  }
  return null;
}

