function generate(rand, size) {
  const day = n => new Date(Date.UTC(2021, 11, 20 + n)).toISOString().slice(0, 10);
  const Purchases = [];
  if (size === 'small') {
    // Offsets cluster around the 7-day boundary so gaps of 0, 7 and 8 days all happen.
    const offsets = [0, 1, 7, 8, 14, 15, 22, 30];
    const count = Math.floor(rand() * 8);
    for (let i = 0; i < count; i++) Purchases.push([i + 1, 1 + Math.floor(rand() * 4), day(offsets[Math.floor(rand() * offsets.length)])]);
  } else {
    for (let i = 0; i < 2000; i++) Purchases.push([i + 1, 1 + Math.floor(rand() * 400), day(Math.floor(rand() * 730))]);
  }
  // Shuffle purchase ids so their order says nothing about the dates.
  const ids = Purchases.map(p => p[0]);
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  Purchases.forEach((p, i) => { p[0] = ids[i]; });
  return [{ Purchases }];
}
